// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;

    function setUp() public { c = new Cooler(); }

    function testFuzz_property(address addr10, address addr28) public {
        vm.assume(addr10 != addr28);

        bytes4 sel = bytes4(keccak256("debt()"));
        bytes memory tail = new bytes(96);
        for (uint256 i = 0; i < 20; i++) {
            tail[0x10 + i] = bytes20(addr10)[i];
        }
        for (uint256 i = 0; i < 20; i++) {
            tail[0x28 + i] = bytes20(addr28)[i];
        }

        uint16 tailLen = uint16(tail.length);
        bytes memory calldataBytes = new bytes(4 + tail.length + 2);
        for (uint256 i = 0; i < 4; i++) calldataBytes[i] = sel[i];
        for (uint256 i = 0; i < tail.length; i++) calldataBytes[4 + i] = tail[i];
        calldataBytes[4 + tail.length] = bytes1(uint8(tailLen >> 8));
        calldataBytes[4 + tail.length + 1] = bytes1(uint8(tailLen));

        (bool ok, bytes memory ret) = address(c).staticcall(calldataBytes);

        require(ok, "call failed");
        address returned;
        if (ret.length >= 32) {
            returned = address(uint160(uint256(bytes32(ret))));
        } else if (ret.length == 20) {
            bytes20 b;
            assembly { b := mload(add(ret, 32)) }
            returned = address(b);
        } else {
            returned = address(0);
        }

        assertTrue(returned == addr28);
    }
}
